mapper.select:
SELECT  FROM com_content c

    LEFT JOIN (
        SELECT target_id,
               SUM(CASE WHEN action_type = 'favorite' THEN 1 ELSE 0 END) AS fav_cnt,
               SUM(CASE WHEN action_type = 'derivation' THEN 1 ELSE 0 END) AS use_cnt
        FROM com_interaction
        WHERE action_type IN ('favorite', 'derivation') AND created_at >= #{since}
        GROUP BY target_id
    ) stat ON stat.target_id = c.id
    LEFT JOIN (
        SELECT target_id, COUNT(*) AS like_cnt
        FROM com_like
        WHERE created_at >= #{since}
        GROUP BY target_id
    ) lik ON lik.target_id = c.id

WHERE c.status = 'public'
AND c.content_type = #{dto.content_type}
AND c.subject = #{dto.subject}
AND c.grade = #{dto.grade}
AND (c.title LIKE CONCAT('%',#{dto.keyword},'%') OR c.description LIKE CONCAT('%',#{dto.keyword},'%') OR c.keywords LIKE CONCAT('%',#{dto.keyword},'%') OR c.lesson_type LIKE CONCAT('%',#{dto.keyword},'%'))

ORDER BY ${orderClause}

SELECT  FROM com_content
WHERE author_id = #{authorId}
AND status = #{status}
ORDER BY updated_at DESC
